  render: args => {
    const container = createChartContainer('Layout quality graph');
    container.style.setProperty('display', 'flex');
    container.style.setProperty('flex-direction', 'column');
    document.body.appendChild(container);
    const processGraphContainer = document.createElement('div');
    processGraphContainer.style.setProperty('width', '100%');
    processGraphContainer.style.setProperty('height', '100%');
    const qualityMetricsBar = document.createElement('div');
    qualityMetricsBar.style.setProperty('float', 'left');
    qualityMetricsBar.style.setProperty('width', '100%');
    qualityMetricsBar.style.setProperty('display', 'flex');
    qualityMetricsBar.style.setProperty('align-items', 'left');
    qualityMetricsBar.style.setProperty('gap', '30px');
    container.appendChild(qualityMetricsBar);
    container.appendChild(processGraphContainer);
    const indexOfDataset = TEST_SETS.findIndex(testSet => testSet.name === args.dataset);
    const selectedDataset = TEST_SETS[indexOfDataset];
    renderGraphAndMetrics(args, processGraphContainer, selectedDataset, qualityMetricsBar);
    return container;
  },
  args: defaultGraphProps,
  parameters: {
    ...SHOW_CONTROLS_CONFIG
  },
